class Tree {
    constructor(
        public readonly left: Tree | null,
        public readonly right: Tree | null
    ) {}

    check(): number {
        if (this.left === null) return 1;
        return 1 + this.left.check() + this.right!.check();
    }
}

function buildTree(depth: number): Tree {
    if (depth === 0) return new Tree(null, null);
    return new Tree(buildTree(depth - 1), buildTree(depth - 1));
}

function main(): void {
    const n = parseInt(process.argv[2], 10);
    const output: string[] = [];

    const stretchDepth = n + 1;
    const stretchCheck = buildTree(stretchDepth).check();
    output.push(
        `stretch tree of depth ${stretchDepth}\t check: ${stretchCheck}`
    );

    const longLivedTree = buildTree(n);

    for (let depth = 4; depth <= n; depth += 2) {
        const iterations = 2 ** (n - depth + 4);
        let sum = 0;

        for (let i = 0; i < iterations; i++) {
            sum += buildTree(depth).check();
        }

        output.push(
            `${iterations}\t trees of depth ${depth}\t check: ${sum}`
        );
    }

    output.push(
        `long lived tree of depth ${n}\t check: ${longLivedTree.check()}`
    );

    process.stdout.write(output.join("\n") + "\n");
}

main();
